  a = fr_add(fr_add(fr_mul(plonk_load_static(PLONK_VEC_S1, index), beta), l), gamma);
  b = fr_add(fr_add(fr_mul(plonk_load_static(PLONK_VEC_S2, index), beta), r), gamma);
  c = fr_add(fr_add(fr_mul(plonk_load_static(PLONK_VEC_S3, index), beta), o), gamma);
  let left = fr_mul(fr_mul(fr_mul(a, b), c), zs);

  let ordering = fr_sub(left, right);

  // (Z \u2212 1)\xB7L\u2081 on the coset
  let lone = fr_mul(plonk_load_scalar(PLONK_SCALAR_LAGRANGE_SCALE), plonk_load_denominator(index));
